var byId = (id) => {
  const s = ROSTER.find((r) => r.id === id);
  if (!s) throw new Error(`unknown character ${id}`);
  return s;
};

// lineart/src/cast/skins.ts
var fromRoster = (id, label, gestures) => {
  const s = byId(id);
  return {
    id: label,
    label: s.role,
    outfit: {
      top: s.top,
      topColor: s.topColor,
      sleeve: s.sleeve,
      bottom: s.bottom,
      bottomColor: s.bottomColor,
      hat: s.hat,
      hatColor: s.hatColor,
      extras: (s.extras ?? []).filter((e) => e !== "glasses"),
      prop: s.prop,
      propColor: s.propColor,
      shoeColor: s.shoeColor
    },
    gestures
  };
};
